#!/usr/bin/env python3
import importlib.util, json, random, sys, copy

def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod

main = load("/workspace/submission/main.py", "mainmod")
ref = load("/workspace/tmp/dev/ref.py", "refmod")
fz = load("/workspace/tmp/dev/fuzz.py", "fuzzmod")

def run_ref(doc):
    try:
        return ref.solve(copy.deepcopy(doc))
    except Exception:
        return {"error": "invalid-input"}

def run_main(doc):
    try:
        return main._solve(copy.deepcopy(doc))
    except main.Invalid:
        return {"error": "invalid-input"}
    except Exception as e:
        return {"crash": repr(e)}

def mutate(doc, r):
    d = copy.deepcopy(doc)
    kind = r.randrange(0, 16)
    def walk(node, path=()):
        # collect containers
        stack = [(node, path)]
        opts = []
        while stack:
            n, p = stack.pop()
            if isinstance(n, dict):
                opts.append((n, p))
                for k, v in n.items():
                    stack.append((v, p + (k,)))
            elif isinstance(n, list):
                opts.append((n, p))
                for i, v in enumerate(n):
                    stack.append((v, p + (i,)))
        return opts
    opts = walk(d)
    n, p = r.choice(opts)
    if kind == 0 and isinstance(n, dict) and n:
        k = r.choice(list(n.keys()))
        del n[k]
    elif kind == 1 and isinstance(n, dict):
        n["zzz_extra"] = 1
    elif kind == 2 and isinstance(n, dict) and n:
        k = r.choice(list(n.keys()))
        n[k] = True if r.random() < .5 else False
    elif kind == 3 and isinstance(n, dict) and n:
        k = r.choice(list(n.keys()))
        n[k] = 1.5
    elif kind == 4 and isinstance(n, dict) and n:
        k = r.choice(list(n.keys()))
        v = n[k]
        if isinstance(v, int):
            n[k] = v + r.choice([1, -1, 10**13, -(10**13), 70000, 2**31, -(2**31) - 1, 9, 257, 65536, 17])
        else:
            n[k] = None
    elif kind == 5 and isinstance(n, list):
        if n: n.pop(r.randrange(len(n)))
    elif kind == 6 and isinstance(n, list):
        n.append(r.choice([1, "x", [1], None]))
    elif kind == 7 and isinstance(n, dict) and n:
        k = r.choice(list(n.keys()))
        n[k] = r.choice(["1", [1], {}, None, "dev", "eval"])
    elif kind == 8:
        # swap two packets times to break monotonic order
        pk = d.get("packets")
        if isinstance(pk, list) and len(pk) > 2:
            i = r.randrange(len(pk) - 1)
            pk[i]["time"], pk[i + 1]["time"] = pk[i + 1]["time"] + 5, pk[i]["time"]
    elif kind == 9:
        pk = d.get("packets")
        if isinstance(pk, list) and pk:
            r.choice(pk)["connection"] = "nosuchid"
    elif kind == 10:
        cs = d.get("connections")
        if isinstance(cs, list) and len(cs) > 1:
            cs[r.randrange(len(cs))]["id"] = cs[0]["id"]
    elif kind == 11:
        cs = d.get("connections")
        if isinstance(cs, list) and cs:
            c = r.choice(cs)
            c["id"] = r.choice(["", "a" * 33, "has space", "dot.name", "uni\u00e9", "tab\tx", "a" * 32 + "-"])
    elif kind == 12:
        cs = d.get("connections")
        if isinstance(cs, list) and cs:
            r.choice(cs)["split"] = r.choice(["test", "DEV", "", None, 1])
    elif kind == 13:
        cfg = d.get("config")
        if isinstance(cfg, dict) and "time_edges" in cfg and isinstance(cfg["time_edges"], list) and len(cfg["time_edges"]) > 1:
            cfg["time_edges"][1] = cfg["time_edges"][0]
        elif isinstance(cfg, dict) and "count_edges" in cfg:
            cfg["count_edges"] = [1]
    elif kind == 14:
        cfg = d.get("config")
        if isinstance(cfg, dict):
            cfg["initial_tokens"] = cfg.get("bucket_capacity", 1) + 1 if isinstance(cfg.get("bucket_capacity"), int) else 999
    elif kind == 15:
        m = d.get("model")
        if isinstance(m, dict):
            m["kernel"] = (m.get("kernel", 1) if isinstance(m.get("kernel"), int) else 1) + 17
    return d

def main_loop(n, seed0):
    r = random.Random(seed0)
    bad = 0
    accepted_mutants = 0
    for i in range(n):
        base = fz.rnd_case(r, npkt=r.randint(0, 30), nconn=r.randint(1, 6))
        m = mutate(base, r)
        a = run_main(m)
        b = run_ref(m)
        if a != b:
            bad += 1
            print("MISMATCH mut seed", seed0, i)
            print(json.dumps(m)[:3000])
            print(" main:", json.dumps(a)[:300] if not isinstance(a, dict) or "crash" in a else "ok-result")
            print(" ref :", json.dumps(b)[:300])
            with open("/workspace/tmp/dev/mutfail_%d_%d.json" % (seed0, i), "w") as fh:
                json.dump(m, fh)
            if bad > 3: break
        elif isinstance(a, dict) and a.get("error") != "invalid-input":
            accepted_mutants += 1
    print("done", seed0, "cases", n, "mismatch", bad, "mutant-still-valid", accepted_mutants)
    return bad

if __name__ == "__main__":
    sys.exit(1 if main_loop(int(sys.argv[1]), int(sys.argv[2])) else 0)
